import static org.junit.Assert.*;

/**
 * Unit tests for ArchiveUtils.sanitize
 */
public class ArchiveUtils_sanitize_TriageGen1Test {

    // Assuming MAX_SANITIZED_NAME_LENGTH is a constant in ArchiveUtils.
    // Since it's not provided in the snippet, I will deduce its behavior 
    // from the logic provided (it affects truncation and dots).
    // For the purpose of these tests, we assume it's a positive integer.









    @Test
    public void testSanitize_TruncationAndDotFilling() {
        // We need to trigger: cs.length > MAX_SANITIZED_NAME_LENGTH
        // Since we don't know the exact value of MAX_SANITIZED_NAME_LENGTH,
        // we provide a very long string to ensure the branch is covered.

        // Construct a string much longer than likely MAX_SANITIZED_NAME_LENGTH
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < 200; i++) {
            sb.append('a');
        }
        String longInput = sb.toString();
        String result = ArchiveUtils.sanitize(longInput);

        // Verify length is capped at MAX_SANITIZED_NAME_LENGTH
        // We can't check the exact length without knowing the constant, 
        // but we can check that the result is not the original length.
        assertNotEquals(longInput.length(), result.length());

        // Check that the tail part (after MAX/3) contains dots
        // If the string was truncated, the logic fills chars[i] = '.'
        // then the loop converts '.' (which is not ISO control and not SPECIALS) 
        // back to '.' in the final StringBuilder.
        assertTrue(result.contains("."));
    }






}

